export type InputAction =
  | 'camera-forward'
  | 'camera-backward'
  | 'camera-left'
  | 'camera-right'
  | 'camera-reset'
  | 'confirm-shot'
  | 'pause'
  | 'scoreboard'
  | 'primary';

export interface PointerSnapshot {
  x: number;
  y: number;
  deltaX: number;
  deltaY: number;
  wheel: number;
  primaryDown: boolean;
}

export interface InputSnapshot {
  readonly pointer: PointerSnapshot;
  isDown(action: InputAction): boolean;
  wasPressed(action: InputAction): boolean;
  wasReleased(action: InputAction): boolean;
}

export interface InputManagerOptions {
  target?: Window;
  pointerTarget?: HTMLElement | Document;
  preventContextMenu?: boolean;
}

const keyActions: Readonly<Record<string, InputAction>> = {
  KeyW: 'camera-forward',
  ArrowUp: 'camera-forward',
  KeyS: 'camera-backward',
  ArrowDown: 'camera-backward',
  KeyA: 'camera-left',
  ArrowLeft: 'camera-left',
  KeyD: 'camera-right',
  ArrowRight: 'camera-right',
  KeyR: 'camera-reset',
  Space: 'confirm-shot',
  Escape: 'pause',
  Tab: 'scoreboard',
};

export class InputManager implements InputSnapshot {
  readonly pointer: PointerSnapshot = { x: 0, y: 0, deltaX: 0, deltaY: 0, wheel: 0, primaryDown: false };

  private readonly target: Window;
  private readonly pointerTarget: HTMLElement | Document;
  private readonly preventContextMenu: boolean;
  private readonly down = new Set<InputAction>();
  private readonly pressed = new Set<InputAction>();
  private readonly released = new Set<InputAction>();
  private disposed = false;

  constructor(options: InputManagerOptions = {}) {
    this.target = options.target ?? window;
    this.pointerTarget = options.pointerTarget ?? document;
    this.preventContextMenu = options.preventContextMenu ?? true;

    this.target.addEventListener('keydown', this.onKeyDown);
    this.target.addEventListener('keyup', this.onKeyUp);
    this.pointerTarget.addEventListener('pointerdown', this.onPointerDown as EventListener);
    this.pointerTarget.addEventListener('pointerup', this.onPointerUp as EventListener);
    this.pointerTarget.addEventListener('pointermove', this.onPointerMove as EventListener);
    this.pointerTarget.addEventListener('wheel', this.onWheel as EventListener, { passive: false });
    if (this.preventContextMenu) this.pointerTarget.addEventListener('contextmenu', this.onContextMenu as EventListener);
    this.target.addEventListener('blur', this.onBlur);
  }

  isDown(action: InputAction): boolean { return this.down.has(action); }
  wasPressed(action: InputAction): boolean { return this.pressed.has(action); }
  wasReleased(action: InputAction): boolean { return this.released.has(action); }

  endFrame(): void {
    this.pressed.clear();
    this.released.clear();
    this.pointer.deltaX = 0;
    this.pointer.deltaY = 0;
    this.pointer.wheel = 0;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.target.removeEventListener('keydown', this.onKeyDown);
    this.target.removeEventListener('keyup', this.onKeyUp);
    this.pointerTarget.removeEventListener('pointerdown', this.onPointerDown as EventListener);
    this.pointerTarget.removeEventListener('pointerup', this.onPointerUp as EventListener);
    this.pointerTarget.removeEventListener('pointermove', this.onPointerMove as EventListener);
    this.pointerTarget.removeEventListener('wheel', this.onWheel as EventListener);
    this.pointerTarget.removeEventListener('contextmenu', this.onContextMenu as EventListener);
    this.target.removeEventListener('blur', this.onBlur);
    this.down.clear();
    this.pressed.clear();
    this.released.clear();
  }

  private setAction(action: InputAction, value: boolean): void {
    const had = this.down.has(action);
    if (value) {
      this.down.add(action);
      if (!had) this.pressed.add(action);
    } else {
      this.down.delete(action);
      if (had) this.released.add(action);
    }
  }

  private readonly onKeyDown = (event: KeyboardEvent): void => {
    const action = keyActions[event.code];
    if (!action) return;
    if (action === 'scoreboard' || action === 'confirm-shot') event.preventDefault();
    this.setAction(action, true);
  };

  private readonly onKeyUp = (event: KeyboardEvent): void => {
    const action = keyActions[event.code];
    if (!action) return;
    this.setAction(action, false);
  };

  private readonly onPointerDown = (event: PointerEvent): void => {
    if (event.button !== 0) return;
    this.pointer.primaryDown = true;
    this.pointer.x = event.clientX;
    this.pointer.y = event.clientY;
    this.setAction('primary', true);
  };

  private readonly onPointerUp = (event: PointerEvent): void => {
    if (event.button !== 0) return;
    this.pointer.primaryDown = false;
    this.pointer.x = event.clientX;
    this.pointer.y = event.clientY;
    this.setAction('primary', false);
  };

  private readonly onPointerMove = (event: PointerEvent): void => {
    this.pointer.x = event.clientX;
    this.pointer.y = event.clientY;
    this.pointer.deltaX += event.movementX;
    this.pointer.deltaY += event.movementY;
  };

  private readonly onWheel = (event: WheelEvent): void => {
    this.pointer.wheel += event.deltaY;
    event.preventDefault();
  };

  private readonly onBlur = (): void => {
    for (const action of this.down) this.released.add(action);
    this.down.clear();
    this.pointer.primaryDown = false;
  };

  private readonly onContextMenu = (event: Event): void => event.preventDefault();
}
