export interface LaunchOptions {
  debug: boolean;
  courseId?: string;
  hole?: number;
}

export function parseLaunchOptions(search: string): LaunchOptions {
  const params = new URLSearchParams(search);
  const courseId = params.get('course')?.trim() || undefined;
  const parsedHole = Number(params.get('hole'));
  const hole = Number.isInteger(parsedHole) && parsedHole > 0 ? parsedHole : undefined;
  return {
    debug: params.get('debug') === '1',
    ...(courseId ? { courseId } : {}),
    ...(hole ? { hole } : {}),
  };
}
