export interface MinimapPoint {
  x: number;
  z: number;
  color?: string;
  radius?: number;
  label?: string;
}

export interface MinimapBounds {
  minX: number;
  maxX: number;
  minZ: number;
  maxZ: number;
}

export class PresentationMinimap {
  readonly element: HTMLDivElement;
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D | null;
  private bounds: MinimapBounds = { minX: -10, maxX: 10, minZ: -10, maxZ: 10 };
  private points: readonly MinimapPoint[] = [];

  constructor() {
    this.element = document.createElement('div');
    this.element.className = 'dev-minimap';
    this.element.hidden = true;
    const title = document.createElement('b');
    title.textContent = 'MINIMAP';
    this.canvas = document.createElement('canvas');
    this.canvas.width = 220;
    this.canvas.height = 150;
    this.ctx = this.canvas.getContext('2d');
    this.element.append(title, this.canvas);
  }

  setVisible(visible: boolean): void { this.element.hidden = !visible; }
  get visible(): boolean { return !this.element.hidden; }

  update(bounds: MinimapBounds, points: readonly MinimapPoint[]): void {
    this.bounds = bounds;
    this.points = points;
    this.draw();
  }

  private draw(): void {
    const ctx = this.ctx;
    if (!ctx) return;
    const { width, height } = this.canvas;
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = 'rgba(8, 13, 20, .86)';
    ctx.fillRect(0, 0, width, height);
    ctx.strokeStyle = 'rgba(255,255,255,.22)';
    ctx.strokeRect(.5, .5, width - 1, height - 1);
    const dx = Math.max(.001, this.bounds.maxX - this.bounds.minX);
    const dz = Math.max(.001, this.bounds.maxZ - this.bounds.minZ);
    for (const point of this.points) {
      const x = ((point.x - this.bounds.minX) / dx) * width;
      const y = height - ((point.z - this.bounds.minZ) / dz) * height;
      ctx.beginPath();
      ctx.fillStyle = point.color ?? '#7cf7d4';
      ctx.arc(x, y, point.radius ?? 4, 0, Math.PI * 2);
      ctx.fill();
      if (point.label) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px system-ui, sans-serif';
        ctx.fillText(point.label, x + 6, y - 5);
      }
    }
  }
}
