import * as THREE from 'three';
import { GAME_CONFIG } from './config/GameConfig';
import { InputManager } from './input';
import './style.css';
import { AppUI } from './ui';

const root = document.querySelector<HTMLDivElement>('#app');
if (!root) throw new Error('Missing #app bootstrap element');

document.title = GAME_CONFIG.title;

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
root.append(renderer.domElement);
const uiRoot = document.createElement('div');
uiRoot.className = 'cpa-layer';
root.append(uiRoot);
new AppUI(uiRoot);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 2, 5);
const input = new InputManager({ pointerTarget: renderer.domElement });

const launchParams = new URLSearchParams(window.location.search);
const debugRequested = launchParams.get('debug') === '1';
let diagnostics: { frame(): void; dispose(): void } | undefined;
if (debugRequested) {
  void import('./dev').then(({ DeveloperDiagnostics, parseLaunchOptions }) => {
    const options = parseLaunchOptions(window.location.search);
    document.documentElement.dataset.debug = '1';
    if (options.courseId) document.documentElement.dataset.debugCourse = options.courseId;
    if (options.hole) document.documentElement.dataset.debugHole = String(options.hole);
    diagnostics = new DeveloperDiagnostics({ root, renderer, scene, camera });
  });
}

const resize = () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
};
window.addEventListener('resize', resize);

renderer.setAnimationLoop(() => {
  renderer.render(scene, camera);
  diagnostics?.frame();
  input.endFrame();
});

window.addEventListener('pagehide', () => {
  input.dispose();
  diagnostics?.dispose();
}, { once: true });
